import itertools, json

topics = ["lithographs", "oil", "sculptures", "watercolors"]
people = ["F", "G", "H", "J"]

# A schedule: positions 0..3; assign each person a distinct topic and a distinct position.
# Each position holds one lecture, with one person and one topic.
solutions = []
for pperm in itertools.permutations(people):      # pperm[pos] = person at that position
    for tperm in itertools.permutations(topics):  # tperm[pos] = topic at that position
        pos_p = {p: i for i, p in enumerate(pperm)}
        pos_t = {t: i for i, t in enumerate(tperm)}
        if not (pos_t["oil"] < pos_t["lithographs"] and pos_t["watercolors"] < pos_t["lithographs"]):
            continue
        if not pos_p["F"] < pos_t["oil"]:
            continue
        if not (pos_p["H"] < pos_p["G"] and pos_p["H"] < pos_p["J"]):
            continue
        solutions.append((pos_p, pos_t))

options = {
    "A": lambda p, t: p["F"] < t["sculptures"],
    "B": lambda p, t: p["H"] < t["lithographs"],
    "C": lambda p, t: t["sculptures"] < p["G"],
    "D": lambda p, t: t["sculptures"] < p["J"],
    "E": lambda p, t: t["watercolors"] < p["G"],
}

must = [k for k, f in options.items() if solutions and all(f(p, t) for p, t in solutions)]
counts = {k: sum(1 for p, t in solutions if f(p, t)) for k, f in options.items()}

if len(must) == 1:
    print(json.dumps({
        "final_answer": must[0],
        "evidence": {"num_solutions": len(solutions), "counts_true": counts, "must_be_true": must}
    }))
else:
    print("UNSUPPORTED")
